    /// The conversation it was to carry on the harness has none of.
    NoConversation,
}

/// Whether the harness said it has no conversation to carry on, as Claude
/// Code's "No conversation found with session ID".
fn no_conversation(said: &str) -> bool {
    let said = said.to_lowercase();
    said.contains("no conversation found")
        || (said.contains("session") && said.contains("not found"))
}

/// What a harness that failed said, in its own words: what it printed on
/// its error output, and how it exited.
fn in_its_own_words(stderr: &str, name: &str, status: std::process::ExitStatus) -> String {
    let stderr = stderr.trim();
    if stderr.is_empty() {
        format!("`{name}` exited with {status}, saying nothing about why")
    } else {
        format!("{stderr}\n(`{name}` exited with {status})")
    }
}

fn build_once(program: &str, project_dir: &Path) -> Result<BuildOutcome> {
    {
        let output = crate::process::command(program)
            .arg("build")
            .current_dir(project_dir)
            .output_logged()?;
        crate::piton_fluency::write_with(program, project_dir);

        // `piton build` prints each written file on stdout, as an absolute
        // path, and everything else on stderr.
        let root = dunce::canonicalize(project_dir)
            .unwrap_or_else(|_| project_dir.to_path_buf());
        let files = String::from_utf8_lossy(&output.stdout)
            .lines()
            .map(str::trim)
            .filter(|line| !line.is_empty())
            .map(|line| relative_to(Path::new(line), &root))
            .collect();

        let report = String::from_utf8_lossy(&output.stderr).trim().to_string();
        Ok(BuildOutcome {
            success: output.status.success(),
            files,
            report: if report.is_empty() && !output.status.success() {
                format!("piton build exited with {}", output.status)
            } else {
                report
            },
            replaced: 0,
        })
    }
